591	export function claimHandoff(record, { handoffId, executorId, currentProblem = null } = {}) {
592	  if (!ID.test(executorId)) throw new Error("invalid claim arguments");
593	  validateCurrentProblem(currentProblem);
594	  validateRecord(record);
595	  const next = structuredClone(record);
596	  if (next.handoff_id !== handoffId)
597	    return { record: next, result: { decision: "STOP_DUPLICATE_OR_STALE" }, changed: false };
598	  if (next.rollover.claim) {
599	    if (currentProblem)
600	      return { record: next, result: { decision: currentProblem }, changed: false };
601	    const result =
602	      next.rollover.claim.executor_id === executorId
603	        ? { decision: "STOP_RECONCILIATION_REQUIRED", launch_allowed: false }
604	        : { decision: "STOP_DUPLICATE_OR_STALE" };
605	    return { record: next, result, changed: false };
606	  }
607	  const result = decideHandoff(next, { currentProblem });
608	  if (result.decision !== "ROLLOVER_READY") return { record: next, result, changed: false };
609	  next.status = "claimed";
610	  next.rollover.claim = { executor_id: executorId };
611	  return { record: next, result: { decision: "CLAIMED", idempotent: false }, changed: true };
612	}
